const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product info
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").all();
console.log('Product:', JSON.stringify(product, null, 2));

// Check rt_variants schema
const schema = db.prepare(\"PRAGMA table_info(rt_variants)\").all();
console.log('rt_variants schema:', JSON.stringify(schema, null, 2));

// Check for variants
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-2028EE'\").all();
console.log('Variants:', JSON.stringify(variants, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Re-check compatible_with_json and description
const product = db.prepare(\"SELECT compatible_with_json, description, specs_json FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('compatible_with_json:', product.compatible_with_json);
console.log('specs_json:', product.specs_json);
console.log('description:', product.description);

// Search for any table that might hold compatibility info
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all().map(c => c.name);
  if (cols.some(c => c.toLowerCase().includes('compat'))) {
    console.log('Table with compat column:', t.name, cols);
  }
}
"

